return [{ json: { cfg: { PESOS, CORTES, STATUS_VALUE, PERFIL_NO_CONTATO, CLOSER_POR_PERFIL, APIFY_TOKEN, APIFY_ACTOR, IMERSAO, PIPELINE_B2C, CUSTO_ESTIMADO }, lead: { id_contato }, t0: Date.now() } }];

